package linter

import (
	"fmt"
	"strconv"
	"strings"
)

type GoVersion struct {
	Major int
	Minor int
}

// GreaterOrEqual performs $v >= $other operation.
//
// In other words, it reports whether $v version constraint can use
// a feature from the $other Go version.
//
// As a special case, Major=0 covers all versions.
func (v GoVersion) GreaterOrEqual(other GoVersion) bool {
	switch {
	case v.Major == 0:
		return true
	case v.Major == other.Major:
		return v.Minor >= other.Minor
	default:
		return v.Major >= other.Major
	}
}

func ParseGoVersion(version string) (GoVersion, error) {
	var result GoVersion
	version = strings.TrimPrefix(version, "go")
	if version == "" {
		return result, nil
	}
	parts := strings.Split(version, ".")
	if len(parts) != 2 {
		return result, fmt.Errorf("invalid Go version format: %s", version)
	}
	major, err := strconv.Atoi(parts[0])
	if err != nil {
		return result, fmt.Errorf("invalid major version part: %s: %w", parts[0], err)
	}
	minor, err := strconv.Atoi(parts[1])
	if err != nil {
		return result, fmt.Errorf("invalid minor version part: %s: %w", parts[1], err)
	}
	result.Major = major
	result.Minor = minor
	return result, nil
}
package linter

import (
	"testing"
)

func TestGoVersionParse(t *testing.T) {
	tests := []struct {
		s     string
		major int
		minor int
	}{
		{"", 0, 0},
		{"1.5", 1, 5},
		{"1.10", 1, 10},
		{"2.0", 2, 0},
		{"2.1", 2, 1},
	}

	runTest := func(x string, wantMajor, wantMinor int) {
		have, err := ParseGoVersion(x)
		if err != nil {
			t.Fatalf("parse %q: %v", x, err)
		}
		if have.Major != wantMajor {
			t.Errorf("parseGoVersion(%s); major: want %d, have %d", x, wantMajor, have.Major)
		}
		if have.Minor != wantMinor {
			t.Errorf("parseGoVersion(%s); minor: want %d, have %d", x, wantMinor, have.Minor)
		}
	}

	for _, test := range tests {
		runTest(test.s, test.major, test.minor)
		runTest("go"+test.s, test.major, test.minor)
	}
}

func TestGoVersionCompare(t *testing.T) {
	tests := []struct {
		version string
		other   string
		want    bool
	}{
		{"", "1.5", true},
		{"", "2.0", true},

		{"1.0", "1.0", true},
		{"1.0", "1.1", false},
		{"1.0", "2.0", false},

		{"1.16", "1.15", true},
		{"1.16", "1.16", true},
		{"1.16", "1.17", false},
		{"1.16", "2.0", false},
		{"1.16", "2.1", false},

		{"2.0", "1.0", true},
		{"2.0", "1.15", true},
		{"2.0", "1.254", true},
		{"2.0", "2.0", true},
		{"2.0", "2.1", false},
	}

	parseGoVersion := func(s string) GoVersion {
		v, err := ParseGoVersion(s)
		if err != nil {
			t.Fatalf("parse %q: %v", s, err)
		}
		return v
	}

	runTest := func(x, y string, want bool) {
		have := parseGoVersion(x).GreaterOrEqual(parseGoVersion(y))
		if have != want {
			t.Errorf("%s >= %s: incorrect result (want %v)", x, y, want)
		}
	}

	for _, test := range tests {
		runTest(test.version, test.other, test.want)
